(() => {
  const api=window.desktop,docs=new CodeDocuments(),models=new Map(),trees=new Map(),expanded=new Set(['']);
  const preview=!api,samples={'README.md':'# Ruang Code Workspace\n\nThis is an editable browser sample, not a local project.\nOpen the desktop app and choose a folder to edit real files.\n','src/main.ts':'type Teammate = { name: string; role: string };\n\nconst team: Teammate[] = [\n  { name: "Rakan", role: "Developer" },\n  { name: "Penyelidik", role: "Researcher" },\n];\n\nexport function welcome(name: string): string {\n  return `Selamat datang, ${name}!`;\n}\n\nconsole.log(team.map(member => welcome(member.name)));\n','src/office.css':'.office {\n  background: #111923;\n  color: #edc17d;\n  display: grid;\n  gap: 16px;\n}\n'};
  let editor=null,diff=null,diffModels=[],busy=false,notice='',error=false,generation=0,loading=false,reviewing=null;
  const key=p=>p.replace(/\\/g,'/').toLowerCase(),title=p=>p.replace(/\\/g,'/').split('/').pop(),m=()=>window.RuangMonaco;
  const language=p=>({js:'javascript',cjs:'javascript',mjs:'javascript',jsx:'javascript',ts:'typescript',tsx:'typescript',json:'json',html:'html',css:'css',scss:'scss',md:'markdown',py:'python',sql:'sql',yaml:'yaml',yml:'yaml',toml:'ini',rs:'rust',go:'go',java:'java',c:'c',h:'c',cpp:'cpp',cs:'csharp',sh:'shell',ps1:'powershell',xml:'xml',svg:'xml',php:'php',rb:'ruby'})[p.split('.').pop().toLowerCase()]||'plaintext';
  const clean=e=>e.message.replace(/^Error invoking remote method '[^']+': Error: /,'');
  function message(text,failed=false){notice=text;error=failed;const el=$('#code-notice');if(el){el.textContent=text;el.classList.toggle('danger',failed)}}
  function stopEditor(){if(editor){const d=docs.current();if(d)d.viewState=editor.saveViewState();editor.dispose();editor=null}}
  function clearModels(){stopEditor();models.forEach(value=>value.dispose());models.clear();trees.clear();expanded.clear();expanded.add('')}
  function treeHTML(relative='',depth=0){const list=trees.get(relative);if(!list)return '<li class="small muted">Loading…</li>';return list.entries.map(entry=>`<li><button class="code-file ${!entry.directory&&key(entry.path)===docs.active?'selected':''}" style="padding-left:${12+depth*14}px" data-code="${entry.directory?'folder':'file'}" data-path="${esc(entry.path)}" ${entry.directory?`aria-expanded="${expanded.has(entry.path)}"`:''} ${!entry.directory&&!entry.editable?'disabled title="Preview unavailable for this file type"':''}><span aria-hidden="true">${entry.directory?(expanded.has(entry.path)?'▾':'▸'):'◇'}</span> ${esc(entry.name)}</button>${entry.directory&&expanded.has(entry.path)?`<ul>${treeHTML(entry.path,depth+1)}</ul>`:''}</li>`).join('')+(list.truncated?'<li class="small muted">First 500 entries shown.</li>':'')}
  function tabsHTML(){return [...docs.documents.entries()].map(([id,d])=>`<div class="code-tab ${id===docs.active?'active':''}"><button role="tab" aria-selected="${id===docs.active}" data-code="tab" data-path="${esc(id)}" title="${esc(d.path)}">${esc(title(d.path))}<span data-dirty="${esc(id)}">${d.draft!==d.original?' ●':''}</span></button><button aria-label="Close ${esc(d.path)}" data-code="close" data-path="${esc(id)}">×</button></div>`).join('')}
  function panel(){const d=docs.current();return `<section class="code-shell"><header class="code-toolbar"><div><strong>${esc(docs.folder?.name||'Your project')}</strong><span class="small muted">${preview?'Sample workspace · browser preview':docs.folder?'Local project':'No folder selected'}</span></div><div><button data-code="choose" ${busy||preview?'disabled':''}>${docs.folder?'Open another folder':'Open project folder'}</button><button data-code="refresh" ${busy||!docs.folder?'disabled':''}>Refresh files</button><button data-code="office">Back to office</button></div></header><div class="code-layout"><aside class="code-explorer"><h2>EXPLORER</h2><p class="small muted code-root" title="${esc(docs.folder?.path||'')}">${esc(docs.folder?.name||'Choose a folder to begin')}</p><ul aria-label="Project files">${docs.folder?treeHTML():''}</ul><p class="small muted code-explorer-note">${preview?'These samples do not read or change your local files.':'UTF-8 text files up to 1 MB. Secret files and links are excluded.'}</p></aside><section class="code-editor-pane"><div class="code-tabs" role="tablist" aria-label="Open files">${tabsHTML()}</div><div class="code-filebar"><span title="${esc(d?.path||'')}">${esc(d?.path||'No file open')}</span><div><button data-code="find" ${!d?'disabled':''}>Find / replace</button><button data-code="reload" ${busy||!d?'disabled':''}>Reload file</button><button class="primary" data-code="review" ${busy||!d?'disabled':''}>Review changes</button></div></div><div id="code-editor-host">${!d?'<div class="code-welcome"><span>⟨ / ⟩</span><h2>A place for your code.</h2><p>Open a file from the explorer.<br>Keep multiple files open, search, and review edits before saving.</p></div>':''}</div><footer class="code-status"><span id="code-position">${d?'Ln 1, Col 1':'Ready'}</span><span>${d?esc(language(d.path))+' · UTF-8':''}</span><span id="code-dirty-count">${docs.dirty().length} unsaved</span></footer></section></div><p id="code-notice" class="code-notice ${error?'danger':''}" role="status">${esc(notice||'Ctrl+F: find · Ctrl+H: replace · Ctrl+S: review before saving')}</p><div class="code-agent-note"><span class="badge demo">Agent execution: demo</span><span>These are your edits. Connected agents are not yet modifying project files.</span></div></section>`}
  function modelFor(d){const id=key(d.path);if(models.has(id))return models.get(id);const bom=d.draft.startsWith('\ufeff');d.bom=bom;const model=m().editor.createModel(bom?d.draft.slice(1):d.draft,language(d.path),m().Uri.parse('inmemory://ruang/'+generation+'/'+encodeURIComponent(d.path)));models.set(id,model);model.onDidChangeContent(()=>{d.draft=(d.bom?'\ufeff':'')+model.getValue();document.querySelectorAll('[data-dirty]').forEach(el=>{if(el.dataset.dirty===id)el.textContent=d.draft!==d.original?' ●':''});const count=$('#code-dirty-count');if(count)count.textContent=docs.dirty().length+' unsaved'});return model}
  function mount(){if(view!=='Code'||!docs.current())return;if(!m()){message('The code editor could not load. Reopen Ruang or rebuild the editor assets.',true);return}const d=docs.current();editor=m().editor.create($('#code-editor-host'),{model:modelFor(d),theme:'ruang-code',automaticLayout:true,fontSize:14,lineHeight:23,fontFamily:'Consolas, monospace',minimap:{enabled:false},scrollBeyondLastLine:false,readOnly:busy,wordWrap:'off',padding:{top:16},ariaLabel:'Code editor: '+d.path});if(d.viewState)editor.restoreViewState(d.viewState);const restored=editor.getPosition();$('#code-position').textContent=`Ln ${restored.lineNumber}, Col ${restored.column}`;editor.onDidChangeCursorPosition(e=>{const el=$('#code-position');if(el)el.textContent=`Ln ${e.position.lineNumber}, Col ${e.position.column}`});editor.addCommand(m().KeyMod.CtrlCmd|m().KeyCode.KeyS,()=>review());editor.focus()}
  const baseBody=bodyView;bodyView=function(p){return view==='Code'?panel():baseBody(p)};
  navs.splice(navs.findIndex(x=>x[0]==='Files'),0,['Code','⌘']);
  const baseRender=render;render=function(){stopEditor();baseRender();if(view==='Code'){const tag=$('.top-actions .badge');if(tag)tag.textContent=preview?'Editor preview':'Local code';mount()}};
  async function listing(relative){if(preview){const prefix=relative?relative+'/':'';const entries=new Map();for(const file of Object.keys(samples)){if(!file.startsWith(prefix))continue;const parts=file.slice(prefix.length).split('/');entries.set(parts[0],{name:parts[0],path:prefix+parts[0],directory:parts.length>1,editable:parts.length===1})}return {entries:[...entries.values()].sort((a,b)=>Number(b.directory)-Number(a.directory)||a.name.localeCompare(b.name)),truncated:false,folder:docs.folder}}return api.listFiles(relative)}
  async function loadTree(relative=''){const epoch=generation,result=await listing(relative);if(epoch!==generation)return;trees.set(relative,result)}
  async function syncFolder(){if(loading)return;loading=true;try{const folder=preview?{name:'ruang-sample',path:'Browser sample',version:1}:(await api.info()).folder;if(folder?.path!==docs.folder?.path||folder?.version!==docs.folder?.version){docs.setFolder(folder);clearModels();generation++}if(folder)await loadTree();}catch(e){message(clean(e),true)}finally{loading=false;if(view==='Code')render()}}
  function confirmDiscard(text){return new Promise(resolve=>{show(`<h2>Unsaved changes</h2><p>${esc(text)}</p><div class="dialog-actions"><button data-close>Keep editing</button><button class="danger" id="code-discard">Discard changes</button></div>`);let answer=false;$('#code-discard').onclick=()=>{answer=true;$('#dialog').close()};$('#dialog').addEventListener('close',()=>resolve(answer),{once:true})})}
  async function chooseFolder(){if(busy)return;if(docs.dirty().length){message('Save or close your unsaved tabs before opening another folder.',true);return}busy=true;try{const folder=await api.chooseFolder();if(folder){docs.setFolder(folder);clearModels();generation++;await loadTree();message('Opened '+folder.name);window.dispatchEvent(new CustomEvent('ruang-folder-changed',{detail:{folder,source:'code'}}))}}catch(e){message(clean(e),true)}finally{busy=false;if(view==='Code')render()}}
  async function openFile(relative){const id=key(relative);if(docs.documents.has(id)){stopEditor();docs.active=id;render();return}const epoch=generation;busy=true;try{const file=preview?{path:relative,content:samples[relative],hash:'preview',version:1}:await api.readFile(relative);if(epoch!==generation)return;stopEditor();docs.open(file);message(preview?'Editing a browser sample. Saving to disk is available in the desktop app.':'Opened '+relative)}catch(e){message(clean(e),true)}finally{busy=false;if(view==='Code')render()}}
  async function closeTab(id){const d=docs.documents.get(id);if(!d)return;if(d.draft!==d.original&&!await confirmDiscard('Discard unsaved changes to '+d.path+'?'))return;stopEditor();docs.close(id,true);models.get(id)?.dispose();models.delete(id);render()}
  function disposeDiff(){diff?.dispose();diff=null;diffModels.forEach(model=>model.dispose());diffModels=[];reviewing=null;$('#dialog').classList.remove('code-review-dialog')}
  function review(){const d=docs.current();if(!d||busy||$('#dialog').open)return;if(d.draft===d.original){message('No changes to save.');return}reviewing={id:docs.active,submitted:d.draft,file:{path:d.path,content:d.draft,hash:d.hash,version:d.version}};show(`<h2>Review ${esc(title(d.path))}</h2><p class="small muted">${esc(d.path)} · Original on the left, your edits on the right.</p><div id="code-diff-host"></div><p id="code-review-status" role="status">${preview?'Browser sample only. No local files will be changed.':'Saving asks for confirmation and keeps the original in .ai-office-backups.'}</p><div class="dialog-actions"><button data-close>Back to editor</button><button class="primary" id="code-save" ${preview?'disabled':''}>Save to disk</button></div>`);$('#dialog').classList.add('code-review-dialog');diffModels=[m().editor.createModel(d.original,language(d.path)),m().editor.createModel(d.draft,language(d.path))];diff=m().editor.createDiffEditor($('#code-diff-host'),{theme:'ruang-code',readOnly:true,originalEditable:false,automaticLayout:true,renderSideBySide:true,minimap:{enabled:false},fontSize:13});diff.setModel({original:diffModels[0],modified:diffModels[1]});$('#code-save').onclick=saveReviewed;$('#dialog').addEventListener('close',disposeDiff,{once:true})}
  async function saveReviewed(){if(!reviewing||busy)return;busy=true;const pending=reviewing,button=$('#code-save'),back=$('#dialog [data-close]');button.disabled=true;back.disabled=true;button.textContent='Waiting for confirmation…';try{const result=await api.saveFile(pending.file);if(result.canceled){$('#code-review-status').textContent='Save canceled. Your edits are still open.';return}docs.saved(pending.id,result,pending.submitted);message(result.unchanged?'File already matches your draft.':'Saved '+result.path+'. Original backed up to '+result.backup);log('Saved local file “'+result.path+'” from Code after review.');persist();$('#dialog').close();render()}catch(e){$('#code-review-status').textContent=clean(e)+' Your edits are still open.'}finally{busy=false;button.disabled=false;back.disabled=false;button.textContent='Save to disk';editor?.updateOptions({readOnly:false})}}
  $('#dialog').addEventListener('cancel',e=>{if(busy&&reviewing)e.preventDefault()});
  window.addEventListener('beforeunload',e=>{if(docs.dirty().length){e.preventDefault();e.returnValue='Unsaved code changes'}});
  // Files and Code share one selected folder. Avoid invalidating another view's drafts.
  document.addEventListener('click',e=>{if(e.target.closest('[data-local="choose"]')&&docs.dirty().length){e.preventDefault();e.stopImmediatePropagation();show('<h2>Unsaved code changes</h2><p>Save or close your unsaved Code tabs before changing the project folder.</p><div class="dialog-actions"><button data-close>Keep editing</button></div>')}},true);
  document.addEventListener('click',async e=>{if(e.target.closest('[data-view="Code"]')){syncFolder();return}const b=e.target.closest('[data-code]');if(!b||busy)return;const action=b.dataset.code,p=b.dataset.path;try{if(action==='choose')await chooseFolder();if(action==='refresh'){await loadTree();for(const folder of expanded)if(folder)await loadTree(folder);message('File tree refreshed. Open drafts are unchanged.');render()}if(action==='office'){view='Office';render()}if(action==='folder'){if(expanded.has(p))expanded.delete(p);else{expanded.add(p);await loadTree(p)}render()}if(action==='file')await openFile(p);if(action==='tab'){stopEditor();docs.active=p;render()}if(action==='close')await closeTab(p);if(action==='find')editor?.getAction('actions.find').run();if(action==='review')review();if(action==='reload'){const d=docs.current();if(!d)return;if(d.draft!==d.original&&!await confirmDiscard('Reload '+d.path+' from disk and discard its unsaved edits?'))return;const updated=preview?{path:d.path,content:samples[d.path],hash:'preview',version:1}:await api.readFile(d.path);stopEditor();const id=docs.active;docs.close(id,true);models.get(id)?.dispose();models.delete(id);docs.open(updated);message('Reloaded '+updated.path);render()}}catch(err){message(clean(err),true)}});
  window.addEventListener('ruang-folder-changed',e=>{if(e.detail.source==='files')syncFolder()});
  syncFolder();render();
})();
